import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { Line } from 'react-chartjs-2';
import Chart from 'chart.js/auto';

const Dolar = () => {
    const [data, setData] = useState([]);
    const [labels, setLabels] = useState([]);
    const [loading, setLoading] = useState(true);
    
    const url = 'https://api.fastforex.io/fetch-one?from=USD&to=MXN'; // URL de la API para obtener el valor actual
    const API_KEY = '7487e94f8f-82434b0371-skncut'; // Asegúrate de que tu API key sea correcta

    // Función para obtener el precio del dólar
    const obtenerPrecioDolar = async () => {
        try {
            const response = await axios.get(url, {
                headers: {
                    'Authorization': `Bearer ${API_KEY}`,
                },
            });
            return response.data.price; // Ajusta según la estructura de la respuesta
        } catch (error) {
            console.error("Error al obtener el precio del dólar:", error);
            return null;
        }
    };

    useEffect(() => {
        const fetchData = async () => {
            setLoading(true); // Establece loading a true al iniciar la carga de datos
            const precios = [];
            const fechas = [];
            for (let i = 0; i < 5; i++) {
                const precio = await obtenerPrecioDolar();
                if (precio !== null) {
                    precios.push(precio);
                    fechas.push(new Date().toLocaleTimeString());
                }
                await new Promise(resolve => setTimeout(resolve, 10000)); // Espera 10 segundos entre las llamadas
            }
            setData(precios);
            setLabels(fechas);
            setLoading(false); // Establece loading a false después de cargar los datos
        };

        fetchData(); // Llama a la función fetchData para cargar los datos inicialmente

        const interval = setInterval(() => {
            fetchData(); // Actualiza los datos cada 60 segundos
        }, 60000); // 60000 milisegundos = 60 segundos

        return () => clearInterval(interval); // Limpia el intervalo al desmontar el componente
    }, []);
    
    const chartData = {
        labels: labels,
        datasets: [
            {
                label: 'Precio del Dólar (MXN)',
                data: data,
                borderColor: 'rgba(75,192,192,1)',
                backgroundColor: 'rgba(75,192,192,0.2)',
                fill: true,
            },
        ],
    };

    return (
        <div>
            <h1>Precio del Dólar en Tiempo Real</h1>
            {loading ? (
                <p>Cargando datos...</p>
            ) : (
                <Line data={chartData} />
            )}
        </div>
    );
};

export default Dolar;
